import Foundation

/// Decides whether a pasteboard change should be recorded.
///
/// Password managers mark secrets with the nspasteboard.org conventions
/// (https://nspasteboard.org). Those are never stored, and neither is anything
/// copied while an ignored app is in front.
public struct CapturePolicy: Codable, Equatable {
    public static let concealedTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
        "de.petermaurer.TransientPasteboardType",
        "com.typeit4me.clipping",
        "Pasteboard generator type",
    ]

    public static let defaultIgnoredApps: [String] = [
        "com.1password.1password",
        "com.agilebits.onepassword7",
        "com.bitwarden.desktop",
        "com.apple.keychainaccess",
        "com.apple.Passwords",
        "com.lastpass.LastPass",
        "in.sinew.Enpass-Desktop",
        "com.dashlane.Dashlane",
    ]

    public var ignoredApps: [String]

    public init(ignoredApps: [String] = CapturePolicy.defaultIgnoredApps) {
        self.ignoredApps = ignoredApps
    }

    public func shouldCapture(types: [String], frontmostBundleID: String?) -> Bool {
        if types.contains(where: Self.concealedTypes.contains) { return false }
        if let id = frontmostBundleID, ignoredApps.contains(where: { $0.caseInsensitiveCompare(id) == .orderedSame }) {
            return false
        }
        return true
    }
}
